$d='M'.round($p[0][0],1).' '.round($p[0][1],1);for($i=0;$i<$n;$i++){$P0=$p[($i+$n-1)%$n];$P1=$p[$i];$P2=$p[($i+1)%$n];$P3=$p[($i+2)%$n];$d.='C'.round($P1[0]+($P2[0]-$P0[0])/6,1).' '.round($P1[1]+($P2[1]-$P0[1])/6,1).','.round($P2[0]-($P3[0]-$P1[0])/6,1).' '.round($P2[1]-($P3[1]-$P1[1])/6,1).','.round($P2[0],1).' '.round($P2[1],1);}
$o="<svg class='stain $cls' viewBox='0 0 200 200' aria-hidden=true style='$css'><path d='{$d}Z' fill='$col'/>";for($k=0;$k<7;$k++){$a=mt_rand(0,628)/100;$r=95+mt_rand(0,12);$o.="<circle cx='".round(100+cos($a)*$r)."' cy='".round(100+sin($a)*$r)."' r='".mt_rand(2,8)."' fill='$col'/>";}return $o.'</svg>';}
